import{_ as t,o as i,c as o,a5 as n}from"./chunks/framework.CsGesDJn.js";const v=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/admin-management/3-10-4-content-moderation-queue/report3_spec_en.md","filePath":"feature/admin-management/3-10-4-content-moderation-queue/report3_spec_en.md"}'),r={name:"feature/admin-management/3-10-4-content-moderation-queue/report3_spec_en.md"};function s(a,e,l,d,c,u){return i(),o("div",null,[...e[0]||(e[0]=[n("<p><strong>3.10.4 Content Moderation Queue</strong></p><p><strong>Function Trigger</strong></p><p>Admin opens /admin/content-moderation to review flagged post content or submissions from FLAGGED users.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: ADMIN. Content moderation administrator with executive authority to approve publications or block violating content.</li><li><strong>Purpose</strong>: Review post content at a specific version. ADMIN approval is required for flagged users; blocking one version permits a revised version to be submitted.</li><li><strong>Interface</strong>: Content Moderation Queue Screen (SCR-ADM-04), comprising a pending moderation table, split-pane comparison review drawer (side-by-side original copy vs. suspect snippet), verdict action buttons, and justification note field.</li><li><strong>Data Processing</strong>: The content/publishing integration supplies postId, contentVersionId, author and content snapshot/reason to create PENDING_MODERATION. Hold scheduled publications when the author becomes FLAGGED. At dispatch, check current account status, version and ADMIN verdict again. APPROVE permits the normal publication workflow/schedule; BLOCK blocks that version and records a selected strike through FR 3.10.5. RED/three ORANGE creates a review request, never an automatic lock.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Content Moderation Queue Screen (SCR-ADM-04, list and modal review interface):</p><ul><li>Left/Header: Sidebar Admin Navigation; Top Header displaying title &quot;Content Moderation Queue&quot;, pending review count, and violation type filter (Policy, Copyright).</li><li>Center: Queue: Post ID, version, author, active YELLOW/ORANGE/RED counters, flag source, reason and time. Review drawer compares the submitted content snapshot and evidence; choose strike severity for confirmed violations and enter justification.</li><li>Buttons: Button &quot;Confirm Violation &amp; Record Strike&quot; (red), Button &quot;Override Warning &amp; Allow Publication&quot; (green), Justification Note input (mandatory when overriding warning), Button &quot;Close&quot;.</li><li>Footer: Table pagination controls (10, 20, 50 rows/page) and daily resolved content items counter.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: moderationId, postId, contentVersionId, decision (approve/block); note at least 10 characters for approve; strikeLevel and justification for block.</li><li><strong>Input optional</strong>: violationCategory, evidence references.</li><li><strong>System data</strong>: creatorId, reviewerId, content snapshot, current account status, activeStrikeCounts, moderation state and revision, reviewedAt.</li><li><strong>Output</strong>: Moderation adjudication outcome JSON payload with HTTP status code 200 OK.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-64</strong>: Moderate post content by immutable version; embedded asset evidence is not an independent approval of every asset.</li><li><strong>BR-35</strong>: Only ADMIN may approve this queue. Manager/Client workflow approval does not satisfy this requirement.</li><li><strong>BR-64</strong>: FLAGGED holds existing scheduled posts and future submissions for ADMIN review. A queued job must recheck status and the exact approved version before dispatch.</li><li><strong>BR-64</strong>: BLOCK applies to the reviewed version; author may revise and resubmit a new version. APPROVE does not immediately publish or bypass schedule and other workflow gates.</li><li><strong>BR-94</strong>: YELLOW is a warning. An active ORANGE strike sets FLAGGED and requires ADMIN approval for publishing; login remains available. RED or three active ORANGE strikes creates a sanction review request under FR 3.10.9; only Admin confirmation deactivates the account.</li><li><strong>BR-95</strong>: Three active, unconverted YELLOW strikes of any violation category produce one independent ORANGE strike. Mark all three source strikes converted and retain their linkage. A fourth YELLOW starts the next batch; six qualifying YELLOW strikes produce two ORANGE strikes. A direct ORANGE can also be recorded. Pardoning a source YELLOW does not pardon the derived ORANGE.</li><li><strong>BR-96</strong>: Each new violation restarts the account clean period of 30 consecutive days without violations. Still-active strikes expire after that clean period, not individually 30 days after creation. Expired or pardoned strikes are not revived; conversion does not count as a second violation. Expiration and pardon preserve immutable history. Removing the last active ORANGE restores publishing eligibility only if no deactivation or activation restriction remains.</li><li><strong>BR-16</strong>: Audit reviewer, post/version, evidence, verdict, strike linkage and justification; concurrent or repeated decisions must not duplicate strikes.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Missing ADMIN authority → MSG39 (403).</li><li>Post/version or moderation item does not exist → MSG38 (404).</li><li>Item already resolved or submitted version changed → conflict (409); reload current state.</li><li>APPROVE note missing or shorter than 10 characters → MSG80; BLOCK without severity/justification → validation error.</li><li>Approval saved → MSG42; reviewed version blocked → MSG43.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>Integration creates or reuses a pending moderation entry for the post version.</li><li>Admin inspects the content snapshot, reason, author status and evidence.</li><li>Admin approves with a note of at least 10 characters, or blocks with severity and justification.</li><li>System atomically validates the pending revision, saves the verdict, records the strike if blocked and audits the action.</li><li>Notify the author by email. Approved versions may continue the normal workflow; blocked versions require revision and a new review.</li><li>Publisher rechecks the exact version and current account/moderation restrictions before dispatch.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>1.a1: Missing post/version → not found; repeated event → reuse the same pending entry.</li><li>3.a1: Missing ADMIN authority or insufficient approval note → MSG39/MSG80.</li><li>4.a1: Another Admin resolved the item or the submitted version changed → conflict; reload, do not apply the old verdict to the new version.</li><li>6.a1: Account becomes FLAGGED/DEACTIVATED or approved version no longer matches → hold publication and re-evaluate the gate.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>Verdict is attached to the reviewed version, with immutable audit and strike linkage.</li><li>FLAGGED publications, including previously scheduled posts, require ADMIN approval.</li><li>BLOCKED_CONFIRMED versions cannot publish; revised versions can re-enter PENDING_MODERATION.</li><li>No RED or ORANGE threshold deactivates an account without FR 3.10.9 Admin confirmation.</li></ul>",14)])])}const g=t(r,[["render",s]]);export{v as __pageData,g as default};
